mapper.select:
/* LeaveFlowMapper.selectLeaveTypeInfo */
SELECT
      A.SYSTEM_YN     AS systemYn
    , A.APRV_USE_YN   AS aprvUseYn
    , A.USE_UNIT_TYPE AS useUnitType
  FROM TB_LEAVE_TYPE_MGMT A
 WHERE A.CMPNY_CD = #{cmpnyCd}
   AND A.LEAVE_CD = #{leaveCd}
 LIMIT 1

/* LeaveFlowMapper.selectDeductibleGrant */
SELECT
      G.GRANT_ID   AS grantId
    , G.GRANT_DAYS AS grantDays
    , G.USED_DAYS  AS usedDays
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD = #{cmpnyCd}
   AND G.USER_CD  = #{userCd}
   AND G.LEAVE_CD = #{leaveCd}
   AND G.DEL_YN   = 'N'
   AND G.STATUS   = 'ACTIVE'
   AND G.AVAIL_FROM_DATE <= #{workYmd}
   AND G.AVAIL_TO_DATE   >= #{workYmd}
   AND (G.GRANT_DAYS - G.USED_DAYS) >= #{neededDays}
 ORDER BY G.AVAIL_TO_DATE ASC, G.GRANT_DATE ASC
 LIMIT 1
 FOR UPDATE

