/* LeaveFlowMapper.cancelLeaveUseByReqId */
UPDATE TB_USER_LEAVE_USE
   SET LEAVE_STATUS  = 'CANCELLED'
     , CANCEL_REASON = #{cancelReason}
     , CANCEL_DATE   = NOW()
     , UPDATE_NO     = #{updateNo}
     , UPDATE_DATE   = NOW()
 WHERE CMPNY_CD     = #{cmpnyCd}
   AND REQ_ID       = #{reqId}
   AND LEAVE_STATUS = 'CONFIRMED'
   AND DEL_YN       = 'N'

mapper.select:
/* LeaveFlowMapper.selectDirectLeaveGrantIdsByCell */
SELECT DISTINCT U.GRANT_ID
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD     = #{cmpnyCd}
   AND U.USER_CD      = #{userCd}
   AND U.LEAVE_CD     = #{leaveCd}
   AND U.START_DATE   = #{workYmd}
   AND U.REQ_ID IS NULL
   AND U.LEAVE_STATUS = 'CONFIRMED'
   AND U.DEL_YN       = 'N'
   AND U.GRANT_ID IS NOT NULL

