/* LeaveFlowMapper.upsertWorkPlanLeave */
INSERT INTO TB_USER_WORK_PLAN (
      CMPNY_CD
    , SITE_CD
    , USER_CD
    , WORK_YMD
    , WORK_PLAN_CD
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
)
VALUES (
      #{cmpnyCd}
    , #{siteCd}
    , #{userCd}
    , #{workYmd}
    , #{leaveCd}
    , #{insertNo}
    , NOW()
    , #{insertNo}
    , NOW()
) AS NEW
ON DUPLICATE KEY UPDATE
      WORK_PLAN_CD = NEW.WORK_PLAN_CD
    , UPDATE_NO    = NEW.UPDATE_NO
    , UPDATE_DATE  = NOW()

